    categories:["Battle of Daugavpils","Operation Barbarossa","German–Soviet War","Bridgehead battles","Latvia in the Second World War"],
    facts:[["Dates","26–30 June 1941"],["Location","Daugavpils · Latvian SSR"],["River","Dvina · Daugava"],["German command","LVI Motorized Corps · Panzer Group 4"],["German spearhead","8th Panzer Division"],["Soviet counterattack","21st Mechanized Corps and supporting formations"],["Associated air command","Luftflotte 1"],["Result","German victory"],["Operational effect","Dvina crossings and eastern-bank bridgehead secured"],["Exact losses","Disputed"]]
