    facts:[["Dates","14–18 July 1941 · wider fighting through 22 July"],["Location","Soltsy and the Shelon corridor · Russian SFSR"],["Soviet command","Northwestern Front · Eleventh Army"],["German command","LVI Motorized Corps · Panzer Group 4"],["German formation isolated","8th Panzer Division"],["Soviet reinforcements","21st Tank · 70th and 237th Rifle Divisions"],["Result","Local Soviet victory"],["German response","Withdrawal and restoration of a shorter corps front"],["Strategic effect","Delayed northern advance; did not reverse campaign"],["Exact losses","Disputed"]]
